"""What-If Digital Twin Computational Simulation Engine.
Enables controlled in silico simulation of altered physiological parameters to evaluate prospective trajectory shifts.
IMPORTANT: This is a computational research simulation, NOT medical or clinical treatment advice.
"""
from typing import Dict, Any, List, Optional
import numpy as np
import copy

DISCLAIMER_TEXT = (
    "RESEARCH SIMULATION ONLY: This is a computational in silico scenario simulation "
    "generated by HeartFailureTwin. It does NOT constitute medical diagnosis, treatment advice, "
    "or clinical prescription. Changing physiological parameters computationally does not guarantee clinical outcomes."
)

class WhatIfSimulationEngine:
    """Simulates physiological modifications on a patient's Digital Twin state."""

    def __init__(self, twin_model):
        self.twin = twin_model

    def run_simulation(
        self,
        base_state: Dict[str, Any],
        scenario_adjustments: Dict[str, float]
    ) -> Dict[str, Any]:
        """Run what-if scenario.
        
        Args:
            base_state: dictionary representation of current DigitalTwinState
            scenario_adjustments: e.g. {
                'heart_rate_bpm': -15.0, # e.g. simulated reduction
                'respiration_rate_bpm': -4.0,
                'scg_mechanical_energy': +5.0, # improved mechanical force
                'pleth_amplitude': +0.5,
                'weight_kg': -2.0 # fluid offloading scenario
            }
            
        Returns:
            Dict containing:
                - base_trajectory
                - simulated_trajectory
                - delta_risk_24h
                - scenario_description
                - disclaimer
        """
        simulated_vitals = copy.deepcopy(base_state["current_vitals"])
        
        # Apply adjustments
        for param, delta in scenario_adjustments.items():
            if param in simulated_vitals:
                simulated_vitals[param] = max(1.0, simulated_vitals[param] + delta)
                
        # Re-evaluate state under simulated parameters using twin
        sim_state = self.twin.update_state_from_vitals(
            patient_id=base_state["patient_id"],
            vitals=simulated_vitals,
            timestamp_sec=base_state["timestamp_sec"]
        )
        
        base_traj = base_state.get("forecast_trajectory", {})
        sim_traj = sim_state.get("forecast_trajectory", {})
        
        base_risk_24h = base_traj.get("24h", base_state["risk_score"])
        sim_risk_24h = sim_traj.get("24h", sim_state["risk_score"])
        delta_risk_24h = round(sim_risk_24h - base_risk_24h, 4)
        
        return {
            "scenario_name": "In Silico Physiological Modulation",
            "adjustments_applied": scenario_adjustments,
            "original_vitals": base_state["current_vitals"],
            "simulated_vitals": simulated_vitals,
            "original_state_label": base_state["state_label"],
            "simulated_state_label": sim_state["state_label"],
            "original_risk": base_state["risk_score"],
            "simulated_risk": sim_state["risk_score"],
            "delta_risk_24h": delta_risk_24h,
            "base_trajectory": base_traj,
            "simulated_trajectory": sim_traj,
            "disclaimer": DISCLAIMER_TEXT
        }
